import{_ as r,o as a,c as s,ag as t}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Framework personnalisé","description":"","frontmatter":{},"headers":[],"relativePath":"fr/bridge/custom.md","filePath":"fr/bridge/custom.md"}'),o={name:"fr/bridge/custom.md"};function i(l,e,n,c,d,u){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="framework-personnalise" tabindex="-1">Framework personnalisé <a class="header-anchor" href="#framework-personnalise" aria-label="Permalink to &quot;Framework personnalisé&quot;">​</a></h1><p>Votre framework n&#39;est pas pris en charge, ou il est très modifié ? Branchez-le vous-même : tous les scripts Nayretis l&#39;utiliseront.</p><p>Le fichier <code>nay_lib/bridge/custom.lua</code> est livré lisible, hors de l&#39;escrow Cfx. Il contient deux tables, une pour le serveur et une pour le client, avec chaque fonction dont les scripts ont besoin : lire le joueur et son métier, l&#39;argent, les objets, les notifications. Chaque fonction est documentée dans le fichier avec ses arguments et les valeurs qu&#39;elle doit renvoyer.</p><h2 id="etapes" tabindex="-1">Étapes <a class="header-anchor" href="#etapes" aria-label="Permalink to &quot;Étapes&quot;">​</a></h2><ol><li><p>Ouvrez <code>nay_lib/bridge/custom.lua</code> et implémentez chaque fonction des tables serveur et client avec les exports ou les événements de votre framework.</p></li><li><p>Dans <code>server.cfg</code>, forcez l&#39;adaptateur personnalisé :</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;custom&quot;</span></span></code></pre></div></li><li><p>Redémarrez le serveur. Le fichier est lu par chaque ressource qui utilise <code>nay_lib</code> : redémarrez-les toutes après chaque modification.</p></li></ol><p>La console le confirme au démarrage : <code>Bridge ready: framework=custom ...</code>.</p><h2 id="ce-que-le-bridge-fait-deja-pour-vous" tabindex="-1">Ce que le bridge fait déjà pour vous <a class="header-anchor" href="#ce-que-le-bridge-fait-deja-pour-vous" aria-label="Permalink to &quot;Ce que le bridge fait déjà pour vous&quot;">​</a></h2><p>Vous n&#39;avez qu&#39;à parler à votre framework. Le bridge lui-même :</p><ul><li>valide les montants et les comptes (<code>cash</code> et <code>bank</code>, montants entiers positifs) ;</li><li>vérifie le solde avant de retirer de l&#39;argent et la quantité avant de retirer des objets ;</li><li>prévient les scripts quand un joueur se déconnecte.</li></ul><p>Besoin d&#39;un coup de main ? Ouvrez un post dans <code>#support</code> sur le <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Discord Nayretis</a>.</p>',10)])])}const f=r(o,[["render",i]]);export{m as __pageData,f as default};
